/**
 * Protocol buffer messages for `frames.proto` (package `pipecat`).
 *
 * PORTING NOTE: upstream's module is generated by `protoc` and needs the
 * `protobuf` runtime. Core takes no third-party dependencies, so this is a
 * hand-written proto3 codec for the same schema, with the same wire format:
 *
 * ```proto
 * message TextFrame { uint64 id = 1; string name = 2; string text = 3; }
 * message AudioRawFrame {
 *   uint64 id = 1; string name = 2; bytes audio = 3; uint32 sample_rate = 4;
 *   uint32 num_channels = 5; optional uint64 pts = 6;
 * }
 * message TranscriptionFrame {
 *   uint64 id = 1; string name = 2; string text = 3; string user_id = 4; string timestamp = 5;
 * }
 * message MessageFrame { string data = 1; }
 * message InterruptionFrame { uint64 id = 1; string name = 2; }
 * message Frame {
 *   oneof frame {
 *     TextFrame text = 1; AudioRawFrame audio = 2; TranscriptionFrame transcription = 3;
 *     MessageFrame message = 4; InterruptionFrame interruption = 5;
 *   }
 * }
 * ```
 *
 * The protobuf Python API maps as: `Message()` / `Message(field=...)` →
 * `new Message({ field })` (camelCase fields), `msg.SerializeToString()` →
 * `msg.serializeToString()`, `Message.FromString(data)` →
 * `Message.fromString(data)`, `msg.WhichOneof("frame")` →
 * `msg.whichOneof("frame")`, and `Message.DESCRIPTOR.fields_by_name[...]` →
 * `Message.DESCRIPTOR.fieldsByName[...]`; each field descriptor carries its
 * proto `name` and the TS property it maps to (`attr`). `uint64` fields are
 * JS numbers (exact up to 2^53). An unset `optional` field reads `null`.
 */

type ScalarKind = "uint64" | "uint32" | "string" | "bytes";

/** Describes one field of a message. */
export interface FieldDescriptor {
  /** The field's proto name (snake_case). */
  readonly name: string;
  /** The TS property holding the field. */
  readonly attr: string;
  /** The field number. */
  readonly number: number;
  /** The field's type. */
  readonly kind: ScalarKind | "message";
  /** Whether the field has explicit presence (`optional`). */
  readonly optional: boolean;
  /** The message type of a message field. */
  readonly messageType: MessageDescriptor | null;
  /** The oneof the field belongs to, if any. */
  readonly oneof: string | null;
}

/** Describes a message type. */
export interface MessageDescriptor {
  /** The message's short name. */
  readonly name: string;
  /** The message's fully qualified name. */
  readonly fullName: string;
  /** The fields, in declaration order. */
  readonly fields: readonly FieldDescriptor[];
  /** The fields, by proto name. */
  readonly fieldsByName: Readonly<Record<string, FieldDescriptor>>;
}

function field(
  name: string,
  attr: string,
  number: number,
  kind: FieldDescriptor["kind"],
  extra: { optional?: boolean; messageType?: MessageDescriptor; oneof?: string } = {},
): FieldDescriptor {
  return {
    name,
    attr,
    number,
    kind,
    optional: extra.optional ?? false,
    messageType: extra.messageType ?? null,
    oneof: extra.oneof ?? null,
  };
}

function descriptor(name: string, fields: FieldDescriptor[]): MessageDescriptor {
  return {
    name,
    fullName: `pipecat.${name}`,
    fields,
    fieldsByName: Object.fromEntries(fields.map((f) => [f.name, f])),
  };
}

//
// Wire format
//

/** Encodes the proto wire format. @internal */
export class Writer {
  #chunks: number[] = [];

  varint(value: number): void {
    let v = Math.floor(value);
    if (v < 0 || !Number.isFinite(v)) {
      throw new RangeError(`value out of range for an unsigned varint: ${value}`);
    }
    while (v >= 0x80) {
      this.#chunks.push((v % 0x80) | 0x80);
      v = Math.floor(v / 0x80);
    }
    this.#chunks.push(v);
  }

  tag(number: number, wireType: number): void {
    this.varint(number * 8 + wireType);
  }

  bytes(data: Uint8Array): void {
    this.varint(data.length);
    for (const b of data) {
      this.#chunks.push(b);
    }
  }

  finish(): Uint8Array {
    return Uint8Array.from(this.#chunks);
  }
}

/** Decodes the proto wire format. @internal */
export class Reader {
  readonly #data: Uint8Array;
  #pos = 0;

  constructor(data: Uint8Array) {
    this.#data = data;
  }

  get done(): boolean {
    return this.#pos >= this.#data.length;
  }

  varint(): number {
    let result = 0;
    let multiplier = 1;
    while (true) {
      if (this.#pos >= this.#data.length) {
        throw new Error("Error parsing message: truncated varint");
      }
      const b = this.#data[this.#pos++] as number;
      result += (b & 0x7f) * multiplier;
      if ((b & 0x80) === 0) {
        return result;
      }
      multiplier *= 0x80;
    }
  }

  take(length: number): Uint8Array {
    if (this.#pos + length > this.#data.length) {
      throw new Error("Error parsing message: truncated field");
    }
    const out = this.#data.slice(this.#pos, this.#pos + length);
    this.#pos += length;
    return out;
  }

  skip(wireType: number): void {
    switch (wireType) {
      case 0:
        this.varint();
        break;
      case 1:
        this.take(8);
        break;
      case 2:
        this.take(this.varint());
        break;
      case 5:
        this.take(4);
        break;
      default:
        throw new Error(`Error parsing message: unsupported wire type ${wireType}`);
    }
  }
}

const encoder = new TextEncoder();
// proto3 `string` fields must be valid UTF-8; upstream's parser rejects others.
const decoder = new TextDecoder("utf-8", { fatal: true });

/** Base class of the generated-style messages. */
export abstract class Message {
  /** The message type's descriptor. */
  static DESCRIPTOR: MessageDescriptor;

  get #descriptor(): MessageDescriptor {
    return (this.constructor as typeof Message).DESCRIPTOR;
  }

  /** Serialize the message to its binary wire format. */
  serializeToString(): Uint8Array {
    const writer = new Writer();
    this._write(writer);
    return writer.finish();
  }

  /** Replace this message's contents with the parsed binary `data`. */
  parseFromString(data: Uint8Array): void {
    // As protobuf's `ParseFromString`: clear the message, then merge `data` into it.
    this.clear();
    this._read(new Reader(data));
  }

  /** Reset every field to its default (unset) value. */
  clear(): void {
    const self = this as unknown as Record<string, unknown>;
    for (const f of this.#descriptor.fields) {
      if (f.optional || f.kind === "message") {
        self[f.attr] = null;
      } else if (f.kind === "string") {
        self[f.attr] = "";
      } else if (f.kind === "bytes") {
        self[f.attr] = new Uint8Array(0);
      } else {
        self[f.attr] = 0;
      }
    }
  }

  /** Whether a field with presence (optional, or a message) is set. */
  hasField(name: string): boolean {
    const f = this.#descriptor.fieldsByName[name];
    if (!f || (!f.optional && f.kind !== "message")) {
      throw new Error(`Field ${name} does not have presence`);
    }
    return (this as unknown as Record<string, unknown>)[f.attr] != null;
  }

  /** @internal */
  _write(writer: Writer): void {
    const self = this as unknown as Record<string, unknown>;
    for (const f of this.#descriptor.fields) {
      const value = self[f.attr];
      if (value == null) {
        continue;
      }
      switch (f.kind) {
        case "uint64":
        case "uint32":
          if (value === 0 && !f.optional) continue;
          writer.tag(f.number, 0);
          writer.varint(value as number);
          break;
        case "string":
          if (value === "" && !f.optional) continue;
          writer.tag(f.number, 2);
          writer.bytes(encoder.encode(value as string));
          break;
        case "bytes":
          if ((value as Uint8Array).length === 0 && !f.optional) continue;
          writer.tag(f.number, 2);
          writer.bytes(value as Uint8Array);
          break;
        case "message":
          writer.tag(f.number, 2);
          writer.bytes((value as Message).serializeToString());
          break;
      }
    }
  }

  /** @internal */
  _read(reader: Reader): void {
    const self = this as unknown as Record<string, unknown>;
    const byNumber = new Map(this.#descriptor.fields.map((f) => [f.number, f]));
    while (!reader.done) {
      const key = reader.varint();
      const number = Math.floor(key / 8);
      const wireType = key % 8;
      const f = byNumber.get(number);
      if (!f) {
        reader.skip(wireType);
        continue;
      }
      switch (f.kind) {
        case "uint64":
        case "uint32": {
          const v = reader.varint();
          self[f.attr] = f.kind === "uint32" ? v % 2 ** 32 : v;
          break;
        }
        case "string":
          try {
            self[f.attr] = decoder.decode(reader.take(reader.varint()));
          } catch (e) {
            if (!(e instanceof TypeError)) throw e;
            throw new Error("Error parsing message: invalid UTF-8 in string field");
          }
          break;
        case "bytes":
          self[f.attr] = reader.take(reader.varint());
          break;
        case "message": {
          const Type = MESSAGE_TYPES[f.messageType?.name ?? ""] as new () => Message;
          const sub = new Type();
          sub.parseFromString(reader.take(reader.varint()));
          self[f.attr] = sub;
          break;
        }
      }
    }
  }
}

