export interface TextFrameOptions {
  id?: number;
  name?: string;
  text?: string;
}

/** `pipecat.TextFrame`. */
export class TextFrame extends Message {
  static override DESCRIPTOR = descriptor("TextFrame", [
    field("id", "id", 1, "uint64"),
    field("name", "name", 2, "string"),
    field("text", "text", 3, "string"),
  ]);

  id: number;
  name: string;
  text: string;

  constructor(options: TextFrameOptions = {}) {
    super();
    this.id = options.id ?? 0;
    this.name = options.name ?? "";
    this.text = options.text ?? "";
  }

  /** Parse a `TextFrame` from its binary wire format. */
  static fromString(data: Uint8Array): TextFrame {
    const message = new TextFrame();
    message.parseFromString(data);
    return message;
  }
}

