/** The members of `Frame`'s `frame` oneof. */
export type FrameOneofName = "text" | "audio" | "transcription" | "message" | "interruption";

export interface FrameOptions {
  text?: TextFrame | null;
  audio?: AudioRawFrame | null;
  transcription?: TranscriptionFrame | null;
  message?: MessageFrame | null;
  interruption?: InterruptionFrame | null;
}

/**
 * `pipecat.Frame`: exactly one of its members is set (the `frame` oneof).
 * Setting a member clears the others, as protobuf does.
 */
export class Frame extends Message {
  static override DESCRIPTOR = descriptor("Frame", [
    field("text", "text", 1, "message", {
      messageType: TextFrame.DESCRIPTOR,
      oneof: "frame",
    }),
    field("audio", "audio", 2, "message", {
      messageType: AudioRawFrame.DESCRIPTOR,
      oneof: "frame",
    }),
    field("transcription", "transcription", 3, "message", {
      messageType: TranscriptionFrame.DESCRIPTOR,
      oneof: "frame",
    }),
    field("message", "message", 4, "message", {
      messageType: MessageFrame.DESCRIPTOR,
      oneof: "frame",
    }),
    field("interruption", "interruption", 5, "message", {
      messageType: InterruptionFrame.DESCRIPTOR,
      oneof: "frame",
    }),
  ]);

  #which: FrameOneofName | null = null;
  #value: Message | null = null;

  constructor(options: FrameOptions = {}) {
    super();
    for (const name of ["text", "audio", "transcription", "message", "interruption"] as const) {
      const value = options[name];
      if (value != null) {
        this.#set(name, value);
      }
    }
  }

  #get<T extends Message>(name: FrameOneofName): T | null {
    return this.#which === name ? (this.#value as T) : null;
  }

  #set(name: FrameOneofName, value: Message | null): void {
    if (value == null) {
      if (this.#which === name) {
        this.#which = null;
        this.#value = null;
      }
      return;
    }
    this.#which = name;
    this.#value = value;
  }

  get text(): TextFrame | null {
    return this.#get("text");
  }
  set text(value: TextFrame | null) {
    this.#set("text", value);
  }

  get audio(): AudioRawFrame | null {
    return this.#get("audio");
  }
  set audio(value: AudioRawFrame | null) {
    this.#set("audio", value);
  }

  get transcription(): TranscriptionFrame | null {
    return this.#get("transcription");
  }
  set transcription(value: TranscriptionFrame | null) {
    this.#set("transcription", value);
  }

  get message(): MessageFrame | null {
    return this.#get("message");
  }
  set message(value: MessageFrame | null) {
    this.#set("message", value);
  }

  get interruption(): InterruptionFrame | null {
    return this.#get("interruption");
  }
  set interruption(value: InterruptionFrame | null) {
    this.#set("interruption", value);
  }

  /**
   * The name of the member of oneof `oneofGroup` that is set, or null.
   *
   * @param oneofGroup The oneof's name; `Frame` has only `"frame"`.
   */
  whichOneof(oneofGroup: "frame"): FrameOneofName | null {
    if (oneofGroup !== "frame") {
      throw new Error(`Protocol message has no oneof "${oneofGroup}" field.`);
    }
    return this.#which;
  }

  /** Parse a `Frame` from its binary wire format. */
  static fromString(data: Uint8Array): Frame {
    const message = new Frame();
    message.parseFromString(data);
    return message;
  }
}

